from html.parser import HTMLParser
class DisplaySpacing(HTMLParser):
 def __init__(self):super().__init__(convert_charrefs=False);self.out=[];self.verbatim=0
 def handle_starttag(self,t,a):
  self.out.append(self.get_starttag_text())
  if t in ('style','script','pre','code'):self.verbatim+=1
 def handle_endtag(self,t):
  self.out.append('</'+t+'>')
  if t in ('style','script','pre','code'):self.verbatim-=1
 def handle_data(self,d):
  if not self.verbatim:
   replacements={'All87inventoryJSON':'All 87 inventory JSON','Every12,316contractconstituents':'All 12,316 contract constituents','Fullschema':'Full schema','Authority/accessgaps':'Authority and access gaps','Ownedassetmanifest':'Owned asset manifest','OfflineQA':'Offline QA','CurrentstateSeptember2026':'Current state · September 2026','2024election-specific':'2024 election-specific','all87county':'all 87 county','as-ofSeptember18,2026':'as of September 18, 2026','printJanuary2026':'print January 2026','FullnativeEsriJSON.gz':'Full native Esri JSON.gz','Actualcounty-linkedWaconia4polygonpreview':'Waconia: county-linked four-polygon preview','ActualcountyPDFpagepreview':'County PDF page preview','OriginalcountyPDF.gz':'Original county PDF.gz','countiesJSON':'counties JSON','PDFsretained':'PDFs retained'}
   for a,b in replacements.items():d=d.replace(a,b)
   d=re.sub(r'(?<=[A-Za-z])(?=\d)',' ',d);d=re.sub(r'(?<=\d)(?=[A-Za-z])',' ',d)
   d=d.replace(';','; ').replace(':',': ').replace('.202', '. 202').replace('No;reference','No; reference').replace('CurrentGPKG','Current GPKG').replace('GPKG.gz',' GPKG.gz').replace('PDF/',' PDF / ').replace('geometryblobs','geometry blobs').replace('completeIDs','complete IDs').replace('sourceVTDID','source VTDID').replace('allrecords','all records')
   d=re.sub(r' {2,}',' ',d)
  self.out.append(d)
 def handle_entityref(self,n):self.out.append('&'+n+';')
 def handle_charref(self,n):self.out.append('&#'+n+';')
 def handle_decl(self,d):self.out.append('<!'+d+'>')
